# ==============================================================
#  Pos-install Windows - servidor local (usa o winget)
#
#  Uso (cole no PowerShell):
#     irm URL_DESTE_ARQUIVO | iex
#
#  Se nao estiver como administrador, ele pede permissao sozinho.
#  So usa o que ja vem no Windows (PowerShell + winget).
#
#  SEGURANCA
#  - Escuta apenas em 127.0.0.1 (ninguem na rede acessa).
#  - Exige um token aleatorio (vai na URL aberta pelo programa).
#  - A pagina nunca envia comandos: so IDs do catalogo ou IDs de pacote
#    do winget, validados com regras estritas.
#
#  Para adicionar programas populares, edite a lista "catalogo" do
#  bloco de dados (DadosB64) ou peca para regenerar este arquivo.
# ==============================================================

$UrlScript = 'https://raw.githubusercontent.com/minitecnico/poslinux/refs/heads/main/pos-install-windows.ps1'

# Textos e catalogo de populares (JSON em UTF-8 -> base64) e a pagina (HTML -> base64).
# Ficam codificados para este arquivo ser ASCII puro e nao quebrar acentos no Windows.
$DadosB64 = ''
$HtmlB64  = ''

function Iniciar-PosInstall {
    $ErrorActionPreference = 'Stop'
    try { [Console]::OutputEncoding = [System.Text.Encoding]::UTF8 } catch { }
    $utf8 = New-Object System.Text.UTF8Encoding($false)

    $Dados = $utf8.GetString([Convert]::FromBase64String($DadosB64)) | ConvertFrom-Json
    $T = $Dados.t
    $Html = $utf8.GetString([Convert]::FromBase64String($HtmlB64))

    # ---------- administrador ----------
    $EhWindows = ($PSVersionTable.PSEdition -eq 'Desktop') -or ($IsWindows -eq $true)
    $EhAdmin = $false
    if ($EhWindows) {
        $identidade = [Security.Principal.WindowsIdentity]::GetCurrent()
        $EhAdmin = (New-Object Security.Principal.WindowsPrincipal($identidade)).IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }

    if ($EhWindows -and (-not $EhAdmin) -and (-not $env:POSINSTALL_SEM_ELEVAR)) {
        Write-Host $T.pedindo_admin -ForegroundColor Yellow
        if ($PSCommandPath) {
            $cmd = "-NoProfile -ExecutionPolicy Bypass -NoExit -File `"$PSCommandPath`""
        } else {
            $cmd = "-NoProfile -ExecutionPolicy Bypass -NoExit -Command `"irm '$UrlScript' | iex`""
        }
        $elevou = $false
        try {
            Start-Process -FilePath 'powershell.exe' -Verb RunAs -ArgumentList $cmd
            $elevou = $true
        } catch {
            Write-Host $T.admin_negado -ForegroundColor Yellow
        }
        if ($elevou) { return }
    }

    # ---------- winget ----------
    $WingetPath = ''
    $cmdWinget = Get-Command winget -ErrorAction SilentlyContinue
    if ($cmdWinget) { $WingetPath = $cmdWinget.Source }
    if (-not $WingetPath) { Write-Host $T.sem_winget -ForegroundColor Yellow }

    # ---------- catalogo de populares ----------
    $MapaCat = @{}
    $CatalogoUi = @()
    foreach ($p in $Dados.catalogo) {
        $MapaCat[$p.id] = $p.winget
        $CatalogoUi += @{ id = $p.id; cat = $p.cat; icone = $p.icone; nome = $p.nome }
    }

    # ---------- token aleatorio ----------
    $bytes = New-Object byte[] 18
    $rng = [System.Security.Cryptography.RandomNumberGenerator]::Create()
    $rng.GetBytes($bytes)
    $Token = [Convert]::ToBase64String($bytes).Replace('+', '-').Replace('/', '_')

    # ---------- abre a porta (somente local) ----------
    $listener = $null
    $porta = 8765
    $hostUsado = '127.0.0.1'
    $ultimoErro = ''
    while (-not $listener) {
        foreach ($nomeHost in @('127.0.0.1', 'localhost')) {
            try {
                $tentativa = New-Object System.Net.HttpListener
                $tentativa.Prefixes.Add("http://${nomeHost}:$porta/")
                $tentativa.Start()
                $listener = $tentativa
                $hostUsado = $nomeHost
                break
            } catch {
                $ultimoErro = $_.Exception.Message
            }
        }
        if (-not $listener) {
            $porta++
            if ($porta -gt 8785) {
                Write-Host $T.sem_porta -ForegroundColor Red
                Write-Host $ultimoErro -ForegroundColor Red
                return
            }
        }
    }

    $S = [hashtable]::Synchronized(@{
        Token    = $Token
        Html     = $Html
        T        = $T
        Winget   = $WingetPath
        Admin    = $EhAdmin
        Porta    = $porta
        Catalogo = $CatalogoUi
        MapaCat  = $MapaCat
        Trava    = (New-Object System.Threading.SemaphoreSlim(1, 1))
    })

    # ==========================================================
    #  Atendimento de cada requisicao (roda em outra "thread")
    # ==========================================================
    $Handler = {
        param($ctx, $S)

        $utf8 = New-Object System.Text.UTF8Encoding($false)
        try { [Console]::OutputEncoding = $utf8 } catch { }
        $req = $ctx.Request
        $res = $ctx.Response
        $T = $S.T

        function Responder-Json($codigo, $obj) {
            $b = $utf8.GetBytes(($obj | ConvertTo-Json -Depth 6 -Compress))
            $res.StatusCode = $codigo
            $res.ContentType = 'application/json; charset=utf-8'
            $res.AddHeader('Cache-Control', 'no-store')
            $res.ContentLength64 = $b.Length
            $res.OutputStream.Write($b, 0, $b.Length)
            $res.OutputStream.Close()
        }

        function Obter-Param($nome) {
            $consulta = $req.Url.Query
            if (-not $consulta) { return '' }
            foreach ($par in $consulta.TrimStart('?').Split('&')) {
                $kv = $par.Split('=', 2)
                if ($kv[0] -eq $nome -and $kv.Count -gt 1) {
                    return [System.Uri]::UnescapeDataString($kv[1].Replace('+', ' '))
                }
            }
            return ''
        }

        function Limpar-Busca($q) {
            $q = [regex]::Replace($q, '[^\p{L}\p{Nd} .+\-]', ' ')
            $q = [regex]::Replace($q, '\s+', ' ').Trim()
            if ($q.Length -gt 60) { $q = $q.Substring(0, 60) }
            return $q
        }

        # Le a tabela de texto que o "winget search" imprime.
        function Ler-Tabela($texto) {
            $saida = New-Object System.Collections.ArrayList
            $linhas = $texto -split "`r?`n"
            $ini = -1
            for ($i = 0; $i -lt $linhas.Count; $i++) {
                if ($linhas[$i] -match '^-{5,}\s*$') { $ini = $i; break }
            }
            if ($ini -lt 0) { return $saida }
            for ($i = $ini + 1; $i -lt $linhas.Count; $i++) {
                $l = $linhas[$i].Trim()
                if (-not $l) { continue }
                $p = [regex]::Split($l, '\s{2,}')
                if ($p.Count -lt 2) { continue }
                $id = $p[1]
                if ($id -match '^[A-Za-z0-9][A-Za-z0-9._+-]{1,127}\z') {
                    $versao = ''
                    if ($p.Count -ge 3) { $versao = $p[2] }
                    $nome = $p[0].TrimEnd([char]0x2026, ' ')
                    [void]$saida.Add([pscustomobject]@{ nome = $nome; id = $id; versao = $versao })
                }
            }
            return $saida
        }

        function Buscar-Winget($q) {
            $wg = $S.Winget
            $argumentos = @('search', '--query', $q, '--source', 'winget', '--accept-source-agreements')
            $texto = (& $wg @argumentos 2>&1 | Out-String)
            return (Ler-Tabela $texto)
        }

        try {
            $porta = $S.Porta
            $hostRecebido = $req.Headers['Host']
            if (($hostRecebido -ne "127.0.0.1:$porta") -and ($hostRecebido -ne "localhost:$porta")) {
                Responder-Json 403 @{ erro = $T.host_invalido }
                return
            }

            $rota = $req.Url.AbsolutePath
            $metodo = $req.HttpMethod

            # ---- pagina ----
            if ($metodo -eq 'GET' -and $rota -eq '/') {
                $b = $utf8.GetBytes($S.Html)
                $res.StatusCode = 200
                $res.ContentType = 'text/html; charset=utf-8'
                $res.AddHeader('Cache-Control', 'no-store')
                $res.ContentLength64 = $b.Length
                $res.OutputStream.Write($b, 0, $b.Length)
                $res.OutputStream.Close()
                return
            }

            # ---- tudo abaixo exige o token ----
            if ($req.Headers['X-Token'] -ne $S.Token) {
                Responder-Json 403 @{ erro = $T.token_invalido }
                return
            }

            if ($metodo -eq 'GET' -and $rota -eq '/api/estado') {
                Responder-Json 200 @{
                    catalogo   = @($S.Catalogo)
                    tem_winget = [bool]$S.Winget
                    admin      = [bool]$S.Admin
                    ocupado    = ($S.Trava.CurrentCount -eq 0)
                }
                return
            }

            # ---- busca ao vivo no winget ----
            if ($metodo -eq 'GET' -and $rota -eq '/api/buscar') {
                $q = Limpar-Busca (Obter-Param 'q')
                if ($q.Length -lt 2) { Responder-Json 200 @{ winget = @(); erros = @() }; return }
                if (-not $S.Winget) { Responder-Json 200 @{ winget = @(); erros = @($T.winget_ausente) }; return }

                $achados = New-Object System.Collections.ArrayList
                foreach ($it in @(Buscar-Winget $q)) { [void]$achados.Add($it) }
                $termos = $q.ToLower().Split(' ')
                if ($termos.Count -gt 1) {                       # "libre office" tambem acha "libreoffice"
                    $vistos = @{}
                    foreach ($it in $achados) { $vistos[$it.id] = $true }
                    foreach ($it in @(Buscar-Winget ($q.Replace(' ', '')))) {
                        if (-not $vistos.ContainsKey($it.id)) { [void]$achados.Add($it) }
                    }
                }

                $ql = $q.ToLower()
                $junto = $ql.Replace(' ', '')
                $pontuados = foreach ($it in $achados) {
                    $n = $it.nome.ToLower()
                    $pts = 3
                    if ($n -eq $ql -or $n -eq $junto) { $pts = 0 }
                    elseif ($n.StartsWith($ql) -or $n.StartsWith($junto)) { $pts = 1 }
                    elseif ($n.Contains($ql) -or $n.Contains($junto) -or $it.id.ToLower().Contains($junto)) { $pts = 2 }
                    [pscustomobject]@{ pts = $pts; tam = $n.Length; nome = $it.nome; id = $it.id; versao = $it.versao }
                }
                $ordenados = @($pontuados | Sort-Object pts, tam, nome | Select-Object -First 60 nome, id, versao)
                Responder-Json 200 @{ winget = $ordenados; erros = @() }
                return
            }

            # ---- instalar ----
            if ($metodo -eq 'POST' -and $rota -eq '/api/instalar') {
                $leitor = New-Object System.IO.StreamReader($req.InputStream, $utf8)
                $corpo = $leitor.ReadToEnd()
                if ($corpo.Length -gt 100000) { Responder-Json 413 @{ erro = $T.pedido_grande }; return }
                try { $j = $corpo | ConvertFrom-Json } catch { Responder-Json 400 @{ erro = $T.pedido_invalido }; return }

                $itens = @($j.itens | Select-Object -Unique)
                $atualizar = [bool]$j.atualizar
                $valido = ($itens.Count -ge 1) -and ($itens.Count -le 300)
                if ($valido) {
                    foreach ($i in $itens) {
                        if ($i -isnot [string]) { $valido = $false; break }
                        if ($i -match '^cat:([A-Za-z0-9_-]{1,40})\z') {
                            if (-not $S.MapaCat.ContainsKey($Matches[1])) { $valido = $false; break }
                        } elseif ($i -notmatch '^win:[A-Za-z0-9][A-Za-z0-9._+-]{1,127}\z') {
                            $valido = $false; break
                        }
                    }
                }
                if (-not $valido) { Responder-Json 400 @{ erro = $T.lista_invalida }; return }
                if (-not $S.Winget) { Responder-Json 400 @{ erro = $T.winget_ausente }; return }
                if (-not $S.Trava.Wait(0)) { Responder-Json 409 @{ erro = $T.em_andamento }; return }

                try {
                    # --- comeca a transmitir o progresso ---
                    $res.SendChunked = $true
                    $res.StatusCode = 200
                    $res.ContentType = 'application/x-ndjson; charset=utf-8'
                    $res.AddHeader('Cache-Control', 'no-store')
                    $saidaHttp = $res.OutputStream
                    $con = @{ ok = $true }

                    function Emitir($obj) {
                        if (-not $con.ok) { return }       # navegador fechou: a instalacao segue ate o fim
                        try {
                            $b = $utf8.GetBytes(($obj | ConvertTo-Json -Compress) + "`n")
                            $saidaHttp.Write($b, 0, $b.Length)
                            $saidaHttp.Flush()
                        } catch { $con.ok = $false }
                    }

                    function Rodar-Winget($argumentos) {
                        $wg = $S.Winget
                        & $wg @argumentos 2>&1 | ForEach-Object {
                            $linha = ([string]$_) -replace '[\x00-\x08\x0B\x0C\x0E-\x1F]', ''
                            foreach ($parte in ($linha -split "`r")) {
                                $p = $parte.Trim()
                                if (-not $p) { continue }
                                if ($p -match '^[-\\|/]+$') { continue }                   # "spinner"
                                if ($p -match '[\u2588\u2593\u2592\u2591]') { continue }   # barra de progresso
                                if ($p -match '^\d+(\.\d+)?\s*[KMG]?B\s*/\s*\d') { continue }
                                Emitir @{ t = 'log'; m = $p }
                            }
                        }
                        return $LASTEXITCODE
                    }

                    $flags = @('--silent', '--accept-package-agreements', '--accept-source-agreements')
                    $JA_INSTALADO = -1978335135        # 0x8A150061
                    $SEM_ATUALIZACAO = -1978335189     # 0x8A15002B

                    if ($atualizar) {
                        Emitir @{ t = 'start'; id = '_update' }
                        $cod = Rodar-Winget (@('upgrade', '--all') + $flags)
                        if ($cod -eq 0 -or $cod -eq $SEM_ATUALIZACAO) { Emitir @{ t = 'ok'; id = '_update' } }
                        else { Emitir @{ t = 'fail'; id = '_update'; codigo = $cod } }
                    }

                    foreach ($chave in $itens) {
                        if ($chave.StartsWith('cat:')) { $wid = $S.MapaCat[$chave.Substring(4)] }
                        else { $wid = $chave.Substring(4) }

                        Emitir @{ t = 'start'; id = $chave }
                        $cod = Rodar-Winget (@('install', '--id', $wid, '--exact', '--source', 'winget') + $flags)
                        if ($cod -eq 0) { Emitir @{ t = 'ok'; id = $chave } }
                        elseif ($cod -eq $JA_INSTALADO -or $cod -eq $SEM_ATUALIZACAO) { Emitir @{ t = 'ok'; id = $chave; obs = $T.ja_instalado } }
                        else { Emitir @{ t = 'fail'; id = $chave; codigo = $cod } }
                    }
                    Emitir @{ t = 'fim'; codigo = 0 }
                } finally {
                    [void]$S.Trava.Release()
                }
                return
            }

            Responder-Json 404 @{ erro = $T.nao_encontrado }
        } catch {
            try { Responder-Json 500 @{ erro = $T.erro_interno } } catch { }
        } finally {
            try { $res.Close() } catch { }
        }
    }

    # ==========================================================
    #  Servidor
    # ==========================================================
    $pool = [runspacefactory]::CreateRunspacePool(1, 8)
    $pool.Open()

    $url = "http://${hostUsado}:$porta/?t=$Token"
    Write-Host ''
    Write-Host $T.rodando -ForegroundColor Green
    Write-Host ($T.abra + '  ' + $url)
    Write-Host $T.encerrar
    Write-Host ''
    if (-not $env:POSINSTALL_SEM_NAVEGADOR) {
        try { Start-Process $url } catch { }
    }

    $ativos = New-Object System.Collections.ArrayList
    try {
        while ($listener.IsListening) {
            $tarefa = $listener.GetContextAsync()
            while (-not $tarefa.AsyncWaitHandle.WaitOne(300)) { }   # acorda a cada 300 ms para aceitar Ctrl+C
            $ctx = $tarefa.Result

            $ps = [powershell]::Create()
            $ps.RunspacePool = $pool
            [void]$ps.AddScript($Handler.ToString()).AddArgument($ctx).AddArgument($S)
            $espera = $ps.BeginInvoke()
            [void]$ativos.Add(@{ Ps = $ps; Espera = $espera })

            foreach ($a in @($ativos)) {                            # limpa o que ja terminou
                if ($a.Espera.IsCompleted) {
                    try { [void]$a.Ps.EndInvoke($a.Espera) } catch { }
                    $a.Ps.Dispose()
                    $ativos.Remove($a)
                }
            }
        }
    } finally {
        try { $listener.Stop() } catch { }
        try { $pool.Close() } catch { }
        Write-Host ''
        Write-Host $T.encerrado
    }
}

Iniciar-PosInstall
